<?php
require_once __DIR__.'/includes/auth.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('INSERT INTO privacy_requests (user_id,request_type,details) VALUES (?,?,?)')->execute([current_user()['id'],$_POST['request_type'],trim($_POST['details'])]);audit_action('privacy_request_created','privacy_requests',(int)$pdo->lastInsertId(),$_POST['request_type']);flash('success','Your privacy request was submitted for review.');redirect('privacy.php');}$requests=$pdo->prepare('SELECT * FROM privacy_requests WHERE user_id=? ORDER BY created_at DESC');$requests->execute([current_user()['id']]);$requests=$requests->fetchAll();$pageTitle='Privacy and data requests';$activePage='privacy';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Governance / Data privacy</div><h1>Privacy and data requests</h1><p>Your resident or staff record is retained for public-service accountability. Access and correction requests are reviewed by an authorized officer.</p></div></section><section class="panel form-panel"><div class="card-header"><div><h2>Submit a request</h2><p class="login-copy">Use this form to request access, correction, ask a privacy question, or file a complaint.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Request type<select name="request_type"><option>Access</option><option>Correction</option><option>Privacy question</option><option>Complaint</option></select></label><label class="wide">Details<textarea name="details" rows="5" required></textarea></label><div class="form-actions"><button class="primary-button">Submit privacy request</button></div></form></section><section class="panel table-panel"><div class="table-toolbar"><h2>My requests</h2><span class="muted"><?= count($requests) ?> requests</span></div><div class="portal-list"><?php foreach($requests as $request): ?><div class="portal-row"><div><strong><?= h($request['request_type']) ?></strong><small><?= h($request['details']) ?> · <?= h(date('M d, Y',strtotime($request['created_at']))) ?></small></div><span class="status-pill <?= h(strtolower(str_replace(' ','-',$request['status']))) ?>"><i></i><?= h($request['status']) ?></span></div><?php endforeach; ?></div></section><?php require __DIR__.'/partials/footer.php'; ?>
